using System.Text;
using FinanceTracker.Generated.Shared;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.Text;

namespace FinanceTracker.Generated.Enums;

[Generator]
public class ServiceDestinationEnumGenerator : IIncrementalGenerator
{
    private const string EnumSourceCode = $$"""
                                            // <auto-generated/>
                                            namespace {{SourceGeneratorConstants.GeneratedNamespace}}.Enums
                                            {
                                                [System.Flags]
                                                internal enum {{SourceGeneratorConstants.ServiceDestinationEnumName}}
                                                {
                                                    Server = 1,
                                                    Client = 2,
                                                }
                                            }
                                            """;

    public void Initialize(IncrementalGeneratorInitializationContext context) =>
        context.RegisterPostInitializationOutput(ctx => ctx.AddSource(
            $"{SourceGeneratorConstants.ServiceDestinationEnumName}Enum.g.cs",
            SourceText.From(EnumSourceCode, Encoding.UTF8)));
}
